const strings = (v: unknown) => (Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : []);
const date = (d: unknown) => (d instanceof Date && !isNaN(d.getTime()) ? d : null);

/** A profile from its plist (the XML inside the CMS envelope of a .mobileprovision). */
export function profileFromPlist(p: Dict, certs: Certificate[]): Profile {
  const ent = ((p.Entitlements ?? {}) as Dict) || {};
  const devices = strings(p.ProvisionedDevices);
  const provisionsAll = p.ProvisionsAllDevices === true;
  const type: ProfileType = provisionsAll ? 'enterprise' : devices.length ? (ent['get-task-allow'] === true ? 'development' : 'ad-hoc') : 'app-store';
  const appId = str(ent['application-identifier']) ?? str(ent['com.apple.application-identifier']);
  const teamIds = strings(p.TeamIdentifier);
  const prefix = strings(p.ApplicationIdentifierPrefix)[0] ?? teamIds[0] ?? null;
  const bundlePattern = appId ? (prefix && appId.startsWith(`${prefix}.`) ? appId.slice(prefix.length + 1) : appId.replace(/^[A-Z0-9]{10}\./, '')) : null;
  return {
    name: str(p.Name),
    uuid: str(p.UUID),
    type,
    appIdName: str(p.AppIDName),
    appId,
    bundlePattern,
    wildcard: !!bundlePattern && bundlePattern.endsWith('*'),
    teamName: str(p.TeamName),
    teamIds,
    platforms: strings(p.Platform),
    created: date(p.CreationDate),
    expires: date(p.ExpirationDate),
    entitlements: ent,
    devices,
    provisionsAll,
    certificates: certs,
  };
}

/** Reads a .mobileprovision file. */
export async function readProfile(buf: Uint8Array): Promise<Profile> {
  const p = envelopePlist(buf);
  if (!p || (!p.UUID && !p.Entitlements)) throw new InspectError('This is not a provisioning profile: no profile plist was found in it.');
  return profileFromPlist(p, await certificates(p));
}

async function certificates(p: Dict): Promise<Certificate[]> {
  const ders = (Array.isArray(p.DeveloperCertificates) ? p.DeveloperCertificates : []).filter((c): c is Uint8Array => c instanceof Uint8Array);
  const out: Certificate[] = [];
  for (const der of ders.slice(0, 50)) out.push({ ...parseCertificate(der), sha1: await sha1(der) });
  return out;
}

async function sha1(der: Uint8Array): Promise<string | null> {
  try {
    const d = new Uint8Array(await crypto.subtle.digest('SHA-1', der.slice()));
    return [...d].map((b) => b.toString(16).padStart(2, '0').toUpperCase()).join('');
  } catch {
    return null;
  }
}

// ---- DER, just enough of X.509 for the subject and validity ----

type Tlv = { tag: number; start: number; end: number; next: number };

function tlv(b: Uint8Array, p: number): Tlv | null {
  if (p + 2 > b.length) return null;
  const tag = b[p];
  let len = b[p + 1];
  let start = p + 2;
  if (len & 0x80) {
    const n = len & 0x7f;
    if (n === 0 || n > 4 || start + n > b.length) return null;
    len = 0;
    for (let i = 0; i < n; i++) len = len * 256 + b[start + i];
    start += n;
  }
  const end = start + len;
  if (end > b.length) return null;
  return { tag, start, end, next: end };
}

function children(b: Uint8Array, t: Tlv): Tlv[] {
  const out: Tlv[] = [];
  for (let p = t.start; p < t.end; ) {
    const c = tlv(b, p);
    if (!c) break;
    out.push(c);
    p = c.next;
  }
  return out;
}

function derTime(b: Uint8Array, t: Tlv): Date | null {
  const s = new TextDecoder().decode(b.subarray(t.start, t.end));
  const m = t.tag === 0x17 ? /^(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})?Z$/.exec(s) : t.tag === 0x18 ? /^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})?Z$/.exec(s) : null;
  if (!m) return null;
  const y = t.tag === 0x17 ? (Number(m[1]) < 50 ? 2000 + Number(m[1]) : 1900 + Number(m[1])) : Number(m[1]);
  const d = new Date(Date.UTC(y, Number(m[2]) - 1, Number(m[3]), Number(m[4]), Number(m[5]), Number(m[6] ?? 0)));
  return isNaN(d.getTime()) ? null : d;
}

/** Subject common name, team (organizational unit) and validity of one DER certificate. */
export function parseCertificate(der: Uint8Array): Omit<Certificate, 'sha1'> {
  const none = { name: null, team: null, notBefore: null, notAfter: null };
  try {
    const cert = tlv(der, 0);
    if (!cert || cert.tag !== 0x30) return none;
    const tbs = children(der, cert)[0];
    if (!tbs || tbs.tag !== 0x30) return none;
    const parts = children(der, tbs);
    const i = parts[0]?.tag === 0xa0 ? 1 : 0;
    const validity = parts[i + 3];
    const subject = parts[i + 4];
    let notBefore: Date | null = null;
    let notAfter: Date | null = null;
    if (validity?.tag === 0x30) {
      const [a, z] = children(der, validity);
      notBefore = a ? derTime(der, a) : null;
      notAfter = z ? derTime(der, z) : null;
    }
    let name: string | null = null;
    let team: string | null = null;
    if (subject?.tag === 0x30) {
      for (const set of children(der, subject)) {
        for (const seq of children(der, set)) {
          const [oid, val] = children(der, seq);
          if (!oid || !val || oid.tag !== 0x06) continue;
          const o = [...der.subarray(oid.start, oid.end)].join('.');
          const v = new TextDecoder().decode(der.subarray(val.start, val.end)).trim();
          if (o === '85.4.3') name = v;
          if (o === '85.4.11') team = v;
        }
      }
    }
    return { name, team, notBefore, notAfter };
  } catch {
    return none;
  }
}

// ---- the .ipa side ----

export type IpaSigning = {
  fileName: string;
  name: string | null;
  bundleId: string | null;
  version: string | null;
  versionCode: string | null;
  /** The embedded.mobileprovision, null when the build has none (unsigned or a simulator build). */
  profile: Profile | null;
  /** Entitlements in the app binary's code signature, null when they could not be read. */
  entitlements: Dict | null;
  backgroundModes: string[];
};

const MAX_SCAN = 600 * 1024 * 1024;

/** Reads the app's Info.plist, its embedded profile and the entitlements it was signed with. */
export async function readIpaSigning(file: File): Promise<IpaSigning> {
  const zip = await openZip(file);
  const infoName = [...zip.entries.keys()].find((n) => /^Payload\/[^/]+\.app\/Info\.plist$/.test(n));
  if (!infoName) throw new InspectError('This is not an iOS app: Payload/*.app/Info.plist is missing.');
  const appDir = infoName.slice(0, -'Info.plist'.length);
  const info = parsePlist(await readEntry(zip, zip.entries.get(infoName)!, 4 * 1024 * 1024));
  if (!info) throw new InspectError('Info.plist could not be read.');
  const profEntry = zip.entries.get(`${appDir}embedded.mobileprovision`);
  const profile = profEntry ? await readProfile(await readEntry(zip, profEntry, 2 * 1024 * 1024)).catch(() => null) : null;
  const exe = typeof info.CFBundleExecutable === 'string' ? zip.entries.get(`${appDir}${info.CFBundleExecutable}`) : undefined;
  const entitlements = exe && exe.size <= MAX_SCAN ? await signedEntitlements(zip, exe).catch(() => null) : null;
  return {
    fileName: file.name,
    name: str(info.CFBundleDisplayName) ?? str(info.CFBundleName),
    bundleId: str(info.CFBundleIdentifier),
    version: str(info.CFBundleShortVersionString),
    versionCode: str(info.CFBundleVersion),
    profile,
    entitlements,
    backgroundModes: strings(info.UIBackgroundModes),
  };
}

/**
 * The XML entitlements blob (magic 0xFADE7171) of the code signature, found by streaming the binary. The magic
 * must be followed by a plist, so a stray match in code is skipped.
 */
async function signedEntitlements(zip: ZipFile, exe: { name: string; method: number; compressedSize: number; size: number; offset: number }): Promise<Dict | null> {
  const reader = (await streamEntry(zip, exe)).getReader();
  let carry = new Uint8Array(0);
  let want = 0;
  let blob: Uint8Array | null = null;
  let filled = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) return null;
      let chunk = value;
      if (blob) {
        const n = Math.min(chunk.length, want - filled);
        blob.set(chunk.subarray(0, n), filled);
        filled += n;
        if (filled >= want) return parsePlist(blob);
        continue;
      }
      const buf = new Uint8Array(carry.length + chunk.length);
      buf.set(carry);
      buf.set(chunk, carry.length);
      chunk = buf;
      for (let i = 0; i + 13 <= chunk.length; i++) {
        if (chunk[i] !== 0xfa || chunk[i + 1] !== 0xde || chunk[i + 2] !== 0x71 || chunk[i + 3] !== 0x71) continue;
        const len = ((chunk[i + 4] << 24) | (chunk[i + 5] << 16) | (chunk[i + 6] << 8) | chunk[i + 7]) >>> 0;
        if (len < 20 || len > 512 * 1024) continue;
        const lead = new TextDecoder().decode(chunk.subarray(i + 8, i + 13));
        if (lead !== '<?xml' && lead !== '<plis') continue;
        want = len - 8;
        blob = new Uint8Array(want);
        const have = chunk.subarray(i + 8, i + 8 + want);
        blob.set(have);
        filled = have.length;
        if (filled >= want) return parsePlist(blob);
        break;
      }
      if (!blob) carry = chunk.subarray(Math.max(0, chunk.length - 12)).slice();
    }
  } finally {
    reader.cancel().catch(() => undefined);
  }
}

// ---- why it will not install ----

export type Problem = { level: 'block' | 'warn' | 'info'; title: string; text: string };

const DAY = 86_400_000;
/** Capabilities Apple does not allow on a wildcard App ID. */
const NOT_ON_WILDCARD: Record<string, string> = {
  'aps-environment': 'push notifications',
  'com.apple.developer.associated-domains': 'associated domains (universal links)',
  'com.apple.developer.in-app-payments': 'Apple Pay',
  'com.apple.developer.applesignin': 'Sign in with Apple',
  'com.apple.developer.icloud-services': 'iCloud',
  'com.apple.developer.healthkit': 'HealthKit',
  'com.apple.developer.homekit': 'HomeKit',
  'com.apple.developer.networking.networkextension': 'Network Extensions',
  'com.apple.security.application-groups': 'App Groups',
};
/** Signed entitlements that are expected to differ from the profile or not appear in it. */
const SKIP_COMPARE = new Set(['application-identifier', 'com.apple.developer.team-identifier', 'keychain-access-groups', 'get-task-allow', 'beta-reports-active']);

export function matchesPattern(bundleId: string, pattern: string): boolean {
  if (pattern === '*') return true;
  if (pattern.endsWith('.*')) return bundleId.startsWith(pattern.slice(0, -1));
  if (pattern.endsWith('*')) return bundleId.startsWith(pattern.slice(0, -1));
  return bundleId === pattern;
}

export function normUdid(u: string): string {
  return u.trim().toLowerCase();
}

export function hasDevice(p: Profile, udid: string): boolean {
  const u = normUdid(udid);
  return p.devices.some((d) => normUdid(d) === u);
}

/**
 * Why a device would refuse this install. `profile` is the profile that decides it (the one inside the .ipa when
 * there is one), `app` the .ipa (null when only a profile was dropped), `udid` the device to check (optional).
 */
export function installProblems(profile: Profile | null, app: IpaSigning | null, udid: string | null, now = Date.now()): Problem[] {
  const out: Problem[] = [];
  if (!profile) {
    if (app) out.push({ level: 'block', title: 'No provisioning profile in this build', text: 'The .ipa has no embedded.mobileprovision, so it is unsigned or built for the simulator. No iPhone or iPad installs it. Export it again from Xcode with Ad Hoc, Development or Enterprise signing.' });
    return out;
  }
  if (profile.expires && profile.expires.getTime() < now) {
    out.push({ level: 'block', title: 'Profile expired', text: `The profile ended on ${day(profile.expires)}. iPhones refuse the install, and apps already installed with it stop opening. Make a new profile in the Apple Developer portal and export the build again.` });
  } else if (profile.expires && profile.expires.getTime() - now < 14 * DAY) {
    out.push({ level: 'warn', title: 'Profile ends soon', text: `The profile ends on ${day(profile.expires)}. After that the build stops installing and opening.` });
  }
  if (profile.type === 'app-store') {
    out.push({ level: 'block', title: 'App Store profile', text: 'An App Store profile is for App Store Connect and TestFlight only. A build signed with it cannot be installed from a link or a cable. Use an Ad Hoc, Development or Enterprise profile to share it with testers.' });
  }
  const certs = profile.certificates.filter((c) => c.notAfter);
  if (certs.length && certs.every((c) => c.notAfter!.getTime() < now)) {
    out.push({ level: 'block', title: 'Every certificate in the profile has expired', text: 'The profile only lists certificates that have expired, so a build signed with one of them does not install. Make a new certificate, a new profile with it, and export again.' });
  }
  if (udid && udid.trim() && (profile.type === 'ad-hoc' || profile.type === 'development')) {
    if (!hasDevice(profile, udid)) {
      out.push({ level: 'block', title: 'This UDID is not in the profile', text: `${udid.trim()} is not one of the ${profile.devices.length} devices of this profile, so this device refuses the install. Register it in the Apple Developer portal, add it to the profile and export the build again.` });
    } else {
      out.push({ level: 'info', title: 'This UDID is in the profile', text: `${udid.trim()} is one of the ${profile.devices.length} devices of this profile.` });
    }
  }
  if (app) {
    if (app.bundleId && profile.bundlePattern && !matchesPattern(app.bundleId, profile.bundlePattern)) {
      out.push({ level: 'block', title: 'Bundle ID does not match the profile', text: `The app is ${app.bundleId}, but the profile is for ${profile.bundlePattern}. iOS refuses a build whose bundle ID is not covered by its profile.` });
    }
    const ent = app.entitlements;
    if (profile.wildcard) {
      const asks = Object.keys(NOT_ON_WILDCARD).filter((k) => (ent ? k in ent : false) || k in profile.entitlements);
      const pushHint = !ent && app.backgroundModes.includes('remote-notification');
      if (asks.length || pushHint) {
        const what = asks.length ? asks.map((k) => NOT_ON_WILDCARD[k]).join(', ') : 'push notifications (remote-notification background mode)';
        out.push({ level: asks.length ? 'block' : 'warn', title: 'Wildcard App ID with capabilities it cannot have', text: `The profile uses the wildcard App ID ${profile.bundlePattern}, and the app uses ${what}. Apple only allows these on an explicit App ID, so the signature does not match what the profile grants. Make an App ID for ${app.bundleId ?? 'the exact bundle ID'} with these capabilities and a profile for it.` });
      }
    }
    if (ent) {
      if (ent['get-task-allow'] === true && profile.entitlements['get-task-allow'] !== true) {
        out.push({ level: 'block', title: 'Debug signing with a distribution profile', text: 'The app was signed for debugging (get-task-allow), but the profile does not allow it. Export with the method that matches the profile, for example Release Testing (Ad Hoc).' });
      }
      const missing = Object.keys(ent).filter((k) => !SKIP_COMPARE.has(k) && !(k in profile.entitlements) && !(profile.wildcard && k in NOT_ON_WILDCARD));
      if (missing.length) {
        out.push({ level: 'block', title: 'Entitlements the profile does not grant', text: `The app was signed with ${missing.join(', ')}, which the profile does not include. iOS refuses an app that asks for more than its profile allows. Turn the capability on for the App ID, make the profile again and export.` });
      }
      const env = str(ent['aps-environment']);
      const pEnv = str(profile.entitlements['aps-environment']);
      if (env && pEnv && env !== pEnv) {
        out.push({ level: 'warn', title: 'Push environment differs', text: `The app asks for aps-environment ${env}, the profile grants ${pEnv}. Push may not reach the app.` });
      }
    } else {
      out.push({ level: 'info', title: 'Signed entitlements not read', text: 'The entitlements in the app binary could not be read in this browser, so only the profile was checked.' });
    }
  }
  if (profile.type === 'development') out.push({ level: 'info', title: 'Developer Mode', text: 'On iOS 16 and later a build with a Development profile only opens with Developer Mode on: Settings, Privacy and Security, Developer Mode.' });
  if (profile.type === 'enterprise') out.push({ level: 'info', title: 'Trust the developer once', text: 'An Enterprise build installs on any device. After installing, the tester trusts the developer once in Settings, General, VPN and Device Management.' });
  const rank = { block: 0, warn: 1, info: 2 } as const;
  return out.sort((a, b) => rank[a.level] - rank[b.level]);
}

export function day(d: Date): string {
  return d.toISOString().slice(0, 10);
}

/** True when the .ipa carries another profile than the one that was dropped next to it. */
export function differentProfile(dropped: Profile | null, embedded: Profile | null): boolean {
  return !!dropped && !!embedded && !!dropped.uuid && !!embedded.uuid && dropped.uuid !== embedded.uuid;
}

